-- Dumping structure for table cbt.cbt_soal
DROP TABLE IF EXISTS `cbt_soal`;
CREATE TABLE IF NOT EXISTS `cbt_soal` (
  `id_soal` int NOT NULL AUTO_INCREMENT,
  `bank_id` int DEFAULT NULL,
  `mapel_id` int DEFAULT '0',
  `jenis` int NOT NULL COMMENT '1=ganda, 2=ganda kompleks, 3=menjodohkan, 4=isian singkat, 5=uraian',
  `nomor_soal` int DEFAULT '0',
  `file` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `file1` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `tipe_file` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `soal` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `opsi_a` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `opsi_b` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `opsi_c` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `opsi_d` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `opsi_e` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `file_a` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `file_b` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `file_c` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `file_d` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `file_e` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `jawaban` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `created_on` int DEFAULT NULL,
  `updated_on` int DEFAULT NULL,
  `tampilkan` int NOT NULL DEFAULT '0',
  `deskripsi` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `kesulitan` int NOT NULL DEFAULT '1' COMMENT 'tingkat kesulitan 1-10',
  `timer` int NOT NULL DEFAULT '0' COMMENT '0=tidak, 1=ya',
  `timer_menit` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id_soal`) USING BTREE,
  UNIQUE KEY `id_soal_idx` (`id_soal`) USING BTREE,
  KEY `id_bank_idx` (`bank_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=740 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;

-- Dumping data for table cbt.cbt_soal: ~428 rows (approximately)
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES
	(1, 7, 0, 1, 1, 'a:0:{}', NULL, NULL, '<p>Sing diarani teks narasi yaiku &hellip;</p>\n', '<p>Teks kang nggambarake sifat-sifat barang kanthi cetha, rinci, lan apa anane.</p>\n', '<p>Asil susastra awujud larik lan pada kang basane cekak, mentes, lan endah.</p>\n', '<p>Teks kang nyritakake sawijining kedadeyan, tindakan, apadene kahanan kanthi urut lan runtut saka wiwitan nganti pungkasan.</p>\n', '<p>Tembang kang kawengku paugeran guru lagu, guru gatra, lan guru wilangan</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'C', 1777092996, 1777092996, 1, '', 8, 0, 0),
	(2, 7, 0, 1, 2, 'a:0:{}', NULL, NULL, '<p>Teks narasi kang isi babagan kisah utawa crita sawijine tokoh sasuwene uripe diarani &hellip;</p>\n', '<p>Teks dongeng</p>\n', '<p>Teks biografi</p>\n', '<p>Teks geguritan</p>\n', '<p>Teks cerita cekak</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'B', 1777092996, 1777092996, 1, '', 8, 0, 0),
	(3, 7, 0, 1, 3, 'a:0:{}', NULL, NULL, '<p><strong>Wacanen teks ing ngisor iki kanggo mangsuli pitakonan nomer 3 - 5!</strong></p><p><strong>Wong Agung Wilis, Pangeran Blambangan</strong></p><p>Wong Agung Wilis utawa Pangeran Putra II minangka sawijining pang&eacute;ran saka Kraton Blambangan sing miyos udakara taun 1680&ndash;1720. Ramane yaiku Pangeran Mas Purba (Prabu Danureja), Raja Blambangan, lan ibune putri saka Kraton Mengwi, Bali.</p><p>Nalika taun 1767, VOC <em>(Vereenigde Oostindische Compagnie) </em>wiwit nguwasani Blambangan lan agawe susah rakyat. Wong Agung Wilis banjur ngumpulak&eacute; prajurit&eacute; lan rakyat saka macem-macem suku; antarane suku Jawa, Bali, Madura, Bugis, Melayu, lan China, sing  dumunung ing Blambangan kanggo nglawan VOC. Dh&egrave;w&egrave;k&eacute; ora mung nglawan langsung ing perang sing diarani Perang Wilis, nanging uga nggawe strategi kanggo narik simpati rakyat, nampa bantuan saka bangsa liya, lan nyerang pangkalan VOC. Nanging, amarga senjata VOC luwih moderen, perlawanan kasebut ora bisa menang.</p><p>Sawis&eacute;, Wong Agung Wilis diasingak&eacute; menyang Pulo Banda, Maluku, bareng karo pirang-pirang pengikut&eacute;. Sawis&eacute; sawetara taun, dh&egrave;w&egrave;k&eacute; bisa uwal lan nglewati sawetara pulo nganti tekan Bali. Wong Agung Wilis tilar donya ing taun 1780 nalika umur&eacute; wis tuwa. Nganti saiki, jeneng&eacute; tetep di&eacute;ling-eling rakyat Banyuwangi minangka pahlawan sing wani mbela tanah kelairan&eacute; saka VOC. </p><p>Apa pengaruh perjuangan Wong Agung Wilis tumrap rakyat Blambangan?</p>\n', '<p>Rakyat dadi luwih wedi marang VOC</p>\n', '<p>Rakyat dadi nyawiji lan nduweni semangat nglawan penjajahan</p>\n', '<p>Rakyat langsung pindhah menyang Bali</p>\n', '<p>VOC langsung ninggalake Blambangan</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'B', 1777092996, 1777092996, 1, '', 8, 0, 0),
	(4, 7, 0, 1, 4, 'a:0:{}', NULL, NULL, '<p>Paragraf kapisan ing teks kuwi nyritakake bab gambaran wiwitan babagan paraga. Babagan iki ing struktur teks biografi diarani &hellip;</p>\n', '<p>Orientasi</p>\n', '<p>Prastawa</p>\n', '<p>Reorientasi</p>\n', '<p>Dudutan </p>\n', '', NULL, NULL, NULL, NULL, NULL, 'A', 1777092996, 1777092996, 1, '', 8, 0, 0),
	(5, 7, 0, 1, 5, 'a:0:{}', NULL, NULL, '<p>Miturut sapa panulise, teks ing dhuwur bisa diarani teks &hellip;</p>\n', '<p>Biografi</p>\n', '<p>Narasi</p>\n', '<p>Dheskripsi</p>\n', '<p>Autobiografi</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'A', 1777092996, 1777092996, 1, '', 8, 0, 0),
	(6, 7, 0, 1, 6, 'a:0:{}', NULL, NULL, '<p><strong>Wacanen teks ing ngisor iki kanggo mangsuli pitakonan nomer 6 - 8!</strong></p><p><strong>Mula Bukane Banyuwangi</strong></p><p>Ing jaman biyen, ana sawijining kerajaan ing pucuk wetan Pulo Jawa sing dipimpin d&eacute;ning Prabu Sulahkrama. Raja iki nduw&eacute; patih sing gagah lan setya jenenge Patih Sidapeksa. Patih Sidapeksa nduw&eacute; bojo ayu lan alus atin&eacute;, jenenge Sri Tanjung. Kaendahan lan kaluhuran budin&eacute; Sri Tanjung nggawe Sang Prabu kepincut lan nduw&eacute; rasa seneng marang dheweke.</p><p>Supaya bisa nduw&eacute;ni Sri Tanjung, Prabu Sulahkrama nggunakak&eacute; akal licik. Patih Sidapeksa diutus lunga nindakak&eacute; tugas adoh sing abot banget. Nalika patih lunga, raja nyoba ngrayu Sri Tanjung, nanging Sri Tanjung tetep setya marang bojone lan nolak rayuan kuwi. Amarga krasa ditolak, raja banjur ngapusi Patih Sidapeksa. Raja kandha yen Sri Tanjung wis tumindak ora becik.</p><p>Nalika Patih bali, dheweke langsung nesu lan ora mikir dawa. Sri Tanjung wis nerangak&eacute; yen dheweke ora salah, nanging Patih tetep ora precaya. Sri Tanjung banjur matur yen dheweke gelem dipat&egrave;ni, nanging yen getihe nggawe banyu kali dadi mambu, teges&eacute; dheweke salah. Nanging yen banyune dadi wangi, teges&eacute; dheweke ora salah.</p><p>Patih Sidapeksa sing kebak nesu banjur mat&egrave;ni Sri Tanjung lan mayit&eacute; dicemplungak&eacute; ing kali sing buthek. Nanging dumadakan banyu kali dadi bening lan mambu wangi. Patih Sidapeksa kaget lan rumangsa salah. Dheweke banjur mbengok, &ldquo;Banyu wangi&hellip; banyu wangi&hellip;&rdquo; Wiwit wektu kuwi, panggonan kasebut diarani Banyuwangi. Crita iki dadi bukti kasetyan lan katresnan Sri Tanjung marang bojone.</p><p>Miturut crita ing dhuwur, piye wewatekane Sri Tanjung?</p>\n', '<p>Wani lan sakkarepe dhewe</p>\n', '<p>Setya lan tulus</p>\n', '<p>Tanggung jawab lan sabar</p>\n', '<p>Jujur lan neriman</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'B', 1777092996, 1777092996, 1, '', 8, 0, 0),
	(7, 7, 0, 1, 7, 'a:0:{}', NULL, NULL, '<p>Sapa paraga protagonis ing crita kuwi?</p>\n', '<p>Prabu Sulahkrama</p>\n', '<p>Patih Sidapeksa</p>\n', '<p>Sri Tanjung</p>\n', '<p>Prajurit kraton</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'C', 1777092996, 1777092996, 1, '', 8, 0, 0),
	(8, 7, 0, 1, 8, 'a:0:{}', NULL, NULL, '<p>Miturut jinise, crita ing ndhuwur kalebu &hellip;</p>\n', '<p>Fabel</p>\n', '<p>Legenda</p>\n', '<p>Sage</p>\n', '<p>Mite</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'B', 1777092996, 1777092996, 1, '', 8, 0, 0),
	(9, 7, 0, 1, 9, 'a:0:{}', NULL, NULL, '<p><strong>Gatekno teks ing ngisor iki kanggo mangsuli pitakon no. 9 - 13!</strong></p><p>Sekar gambuh ping catur,</p><p>Kang cinatur polah kang kalantur,</p><p>Tanpa tutur katula-tula katali,</p><p>Kadaluwarsa katutuh,</p><p>Kapatuh pan dadi awon. </p><p>Teks macapat ing ndhuwur nduweni paugeran &hellip;</p>\n', '<p>4 gatra, 12i, 6a, 8i, 8a</p>\n', '<p>4 gatra, 12 u, 6a, 8i, 12a</p>\n', '<p>5 gatra, 7u, 10u, 12i, 8u, 8o</p>\n', '<p>5 gatra, 12u, 8i, 8u, 8i, 8o</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'C', 1777092996, 1777092996, 1, '', 8, 0, 0),
	(10, 7, 0, 1, 10, 'a:0:{}', NULL, NULL, '<p>Miturut paugerane, tembang ing dhuwur diarani&hellip;</p>\n', '<p>Maskumambang </p>\n', '<p>Megatruh</p>\n', '<p>Gambuh</p>\n', '<p>Pucung</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'C', 1777092996, 1777092996, 1, '', 8, 0, 0),
	(11, 7, 0, 1, 11, 'a:0:{}', NULL, NULL, '<p>Tembang ing dhuwur nggambarake laku uripe manungsa nalika &hellip;</p>\n', '<p>Ana ing kandhutan&eacute; ibun&eacute;, durung kaweruhan lanang apa wadon</p>\n', '<p>Winih sing wis lair, wiwitaning ngambah ing alam donya, isih suci, isih ringkih, kudu dijaga, kudu direngkuh</p>\n', '<p>Kudu digandheng utawi dituntun supaya bisa jumangkah ing wektu sesok </p>\n', '<p>Wis ketemu jodoh sing cocog ing ati, ngelebur dadi siji</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'D', 1777092996, 1777092996, 1, '', 8, 0, 0),
	(12, 7, 0, 1, 12, 'a:0:{}', NULL, NULL, '<p>Jinising tembang macapat sing nggambarake laku uripe manungsa nalika urip kebak kabagyan yaiku &hellip;</p>\n', '<p>Dhandanggula </p>\n', '<p>Asmaradhana</p>\n', '<p>Pangkur</p>\n', '<p>Megatruh</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'A', 1777092996, 1777092996, 1, '', 8, 0, 0),
	(13, 7, 0, 1, 13, 'a:0:{}', NULL, NULL, '<p>Ilmu iku kelakone kanthi laku,</p><p>Lekase lawan kas,</p><p>Tegese kas &hellip;&hellip;&hellip;&hellip;,</p><p>Setya budya pangekese dur angkara. </p><p>Tembang ing nduwur kalebu tembang macapat &hellip;</p>\n', '<p>Maskumambang</p>\n', '<p>Megatruh</p>\n', '<p>Pocung</p>\n', '<p>Gambuh</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'C', 1777092996, 1777092996, 1, '', 8, 0, 0),
	(14, 7, 0, 1, 14, 'a:0:{}', NULL, NULL, '<p>Tembung sing cocok kanggo njangkepi gatra katelu yaiku &hellip;</p>\n', '<p>Nyantosani</p>\n', '<p>Kalangkung</p>\n', '<p>Nyawiji</p>\n', '<p>Ngelmu luhung</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'A', 1777092996, 1777092996, 1, '', 8, 0, 0),
	(15, 7, 0, 1, 15, 'a:0:{}', NULL, NULL, '<p>Sing diarani geguritan yaiku &hellip;</p>\n', '<p>Tembang kang kawengku paugeran guru lagu, guru gatra, lan guru wilangan.</p>\n', '<p>Teks kang nggambarake sifat-sifat barang kanthi cetha, rinci, lan apa anane.</p>\n', '<p>Asil susastra awujud larik lan pada kang basane cekak, mentes, lan endah.</p>\n', '<p>Teks kang nyritakake sawijining kedadeyan, tindakan, apadene kahanan kanthi urut lan runtut saka wiwitan nganti pungkasan.</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'C', 1777092996, 1777092996, 1, '', 8, 0, 0),
	(16, 7, 0, 1, 16, 'a:0:{}', NULL, NULL, '<p>Geguritan kaperang dadi loro, yaiku gagrak lawas lan gagrak anyar. Sing dadi pambeda yaiku&hellip;</p>\n', '<p>Geguritan gagrak lawas nganggo basa Jawa kuna, geguritan gagrak anyar nganggo basa moderen</p>\n', '<p>Gegurtian gagrak lawas dianggit ing jaman ndisik, gagrak anyar dianggit ing jaman saiki</p>\n', '<p>Geguritan gagrak lawas kudu manut aturan kuna, gagrak anyar bebas</p>\n', '<p>Geguritan gagrak lawas dienggo tiyang sepuh, gagrak anyar kanggo bocah nom</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'C', 1777092996, 1777092996, 1, '', 8, 0, 0),
	(17, 7, 0, 1, 17, 'a:0:{}', NULL, NULL, '<p>Geguritan nduweni struktur fisik lan struktur batin, sing kalebu struktur batin yaiku &hellip;</p>\n', '<p>Tema</p>\n', '<p>Diksi</p>\n', '<p>Majas</p>\n', '<p>Tipografi</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'A', 1777092996, 1777092996, 1, '', 8, 0, 0),
	(18, 7, 0, 1, 18, 'a:0:{}', NULL, NULL, '<p><strong>Gatekna gegurtan ing ngisor iki!</strong></p><p><strong>Esuk Awan Sore</strong></p><p>Esuk, awan, sore, ra tau ing omah</p><p>Lunga nggo buku sagudhang </p><p>Ora bisa emoh wegah</p><p>Najemake pikir nggolek pepadhang</p><p>	Esuk, awan, sore, ra tau ing omah</p><p>	Kekurung aneng kandhang ilmu</p><p>Ngrasakake bungah susah</p><p>Kanggo nyekel sing dituju</p><p>Esuk, awan, sore, ra tau ing omah</p><p>Pitakonan njlimet ing ben dina dipangan</p><p>Kabeh kudu bisa kekambah</p><p>Latihan mrantasi alangan panguripan</p><p>	Esuk, awan, sore, ra tau ing omah</p><p>	Kabeh kudu genah ra oleh salah</p><p>	Rasane pengin balik wae dadi bocah</p><p>	Mung ngguya-ngguyu ngrungokake critane simbah</p><p>(<em>PS. No. 21 - 25 Mei 2020</em>)</p><p>Tembung <em>omah-wegah-susah, </em>lan <em>ilmu-dituju, </em>migunakake purwakanthi &hellip;</p>\n', '<p>Guru swara</p>\n', '<p>Guru sastra</p>\n', '<p>Guru basa</p>\n', '<p>Guru lagu</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'A', 1777092996, 1777092996, 1, '', 8, 0, 0),
	(19, 7, 0, 1, 19, 'a:0:{}', NULL, NULL, '<p>Teks geguritan ing ndhuwur nduweni tema ...</p>\n', '<p>Pakunjara</p>\n', '<p>Golek ilmu</p>\n', '<p>Kasusahan</p>\n', '<p>Nasib kang ala</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'B', 1777092996, 1777092996, 1, '', 8, 0, 0),
	(20, 7, 0, 1, 20, 'a:0:{}', NULL, NULL, '<p>Supaya bisa ngasilake tembung kang cekak, menthes, lan endah, geguritan nggunakake basa rinengga. Sing diarani basa rinengga yaiku &hellip;</p>\n', '<p>Tatanan larik, pada, ukara, tembung, lan uni supaya ngasilake sawijine wujud fisik kang kuwawa nyengkuyung isi, rasa, lan swasana</p>\n', '<p>Punjering babagan kang kadadekake ing sajroning geguritan</p>\n', '<p>Basa kang rinakit kanthi cara nggayutake siji tembung karo liyane saengga dadi basa kang endah lan ngresepake</p>\n', '<p>Sikap pangripta marang pamaos.</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'C', 1777092996, 1777092996, 1, '', 8, 0, 0),
	(21, 7, 0, 1, 21, 'a:0:{}', NULL, NULL, '<p>Salah sawijining basa rinengga yaiku tembung entar. Apa sing dikarepake tembung entar?</p>\n', '<p>Tembung loro kang padha utawa meh padha tegese dienggo bebarengan, lumrahe ngemu surasa banget</p>\n', '<p>Tembung kang nduweni teges dudu salugune/ora sabenere</p>\n', '<p>Gandhenge tembung loro didadekake siji murih sudane wandane</p>\n', '<p>Runtuting swara, sastra, utawa basa ing sajroning ukara</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'B', 1777092996, 1777092996, 1, '', 8, 0, 0),
	(22, 7, 0, 1, 22, 'a:0:{}', NULL, NULL, '<p>Saka geguritan <em>Esuk, Awan, Sore, </em>sing kalebu tembung entar yaiku &hellip;</p>\n', '<p>Bungah susah</p>\n', '<p>Najemake pikir</p>\n', '<p>Pitakonan njlimet</p>\n', '<p>Ngguya-ngguyu </p>\n', '', NULL, NULL, NULL, NULL, NULL, 'B', 1777092996, 1777092996, 1, '', 8, 0, 0),
	(23, 7, 0, 1, 23, 'a:0:{}', NULL, NULL, '<p>Tembung <em>emoh wegah </em>bisa dadi salah sawijining basa rinengga sing diarani &hellip;</p>\n', '<p>Tembung entar</p>\n', '<p>Tembung saroja</p>\n', '<p>Tembung garba</p>\n', '<p>Tembung saloka</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'B', 1777092996, 1777092996, 1, '', 8, 0, 0),
	(24, 7, 0, 1, 24, 'a:0:{}', NULL, NULL, '<p>Tembung <em>aneng</em> saka geguritan ing nduwur bisa dadi tuladha tembung garba. Tembung <em>aneng</em> asale saka tembung &hellip;</p>\n', '<p>ana + ing</p>\n', '<p>a + neng</p>\n', '<p>ane + ng</p>\n', '<p>an + eng</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'A', 1777092996, 1777092996, 1, '', 8, 0, 0),
	(25, 7, 0, 1, 25, 'a:0:{}', NULL, NULL, '<p>Tembung loro kang padha utawa meh padha tegese dienggo bebarengan lan lumrahe ngemu surasa pepindhan diarani &hellip;</p>\n', '<p>Tembung garba</p>\n', '<p>Tembung entar</p>\n', '<p>Tembung saloka</p>\n', '<p>Tembung saroja</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'D', 1777092996, 1777092996, 1, '', 8, 0, 0),
	(26, 7, 0, 1, 26, 'a:0:{}', NULL, NULL, '<p><img src="uploads/bank_soal/img_7126_39843be1daf6b576bd1d.png"></p><p>Apa jeneng perang sing dumadi ing Banyuwangi?</p>\n', '<p>Puputan Bayu</p>\n', '<p>Tutukan Sayu</p>\n', '<p>Guputan Sayu</p>\n', '<p>Kukutan Bayu</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'A', 1777092996, 1777092996, 1, '', 8, 0, 0),
	(27, 7, 0, 1, 27, 'a:0:{}', NULL, NULL, '<p>Sapa wae sing nyebabake perang kuwi?</p>\n', '<p>Indonesia lan Belanda</p>\n', '<p>Indonesia lan Inggris</p>\n', '<p>Inggris lan Belanda</p>\n', '<p>Indonesia lan Portugis</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'C', 1777092996, 1777092996, 1, '', 8, 0, 0),
	(28, 7, 0, 1, 28, 'a:0:{}', NULL, NULL, '<p>Kapan dumadine perang kuwi?</p>\n', '<p>Tahun 1767</p>\n', '<p>Tahun 1945</p>\n', '<p>Tahun 1787</p>\n', '<p>Tahun 1929</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'A', 1777092996, 1777092996, 1, '', 8, 0, 0),
	(29, 7, 0, 1, 29, 'a:0:{}', NULL, NULL, '<p>Kanggo nulis tembung manca kang dicethakake, khususe tembung Arab, aksara sing diperlokake yaiku &hellip;</p>\n', '<p>Aksara murda</p>\n', '<p>Aksara swara</p>\n', '<p>Aksara rekan</p>\n', '<p>Aksara legena</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'C', 1777092996, 1777092996, 1, '', 8, 0, 0),
	(30, 7, 0, 1, 30, 'a:0:{}', NULL, NULL, '<p>Ana maneka asil susastra Jawa, salah sijine teks drama. Sing mbedakake teks drama saka asil susastra liyane yaiku &hellip;</p>\n', '<p>Ana sawetara paraga</p>\n', '<p>Nggur ana ing jaman modern</p>\n', '<p>Nyritakne crita padinan</p>\n', '<p>Lumrahe ditata kanggo pementasan ing panggung</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'D', 1777092996, 1777092996, 1, '', 8, 0, 0),
	(31, 7, 0, 1, 31, 'a:0:{}', NULL, NULL, '<p><strong>Wacanen teks ing ngisor iki kanggo mangsuli pitakonan nomer 31 - 37!</strong></p><p><strong><em>	</em></strong><em>Sawise Resi Bhisma lan Pandhita Durna gugur ing payudan, Adipati Karna madeg senapatine Kurawa adhep-adhepan karo Arjuna minangka senapatine Pandhawa. Nalika adhep arep, Arjuna tumuli maju nyedhak marang kakange, Karna.</em></p><p>Arjuna 	: <em>(ngampet metune luh)</em> &ldquo;Kakang Karna, sembah bekti kula kagem Kakang. Sampun kinira kula sowan wonten mriki kangge ngaturaken perang. Kakang, kanthi sadaya raos urmat kula, mangga kula dherekaken dhateng panggenanipun kadang Pandhawa, Kakang.&rdquo;</p><p>Adipati Karna	: &ldquo;Dhuh, dhuh, rayiku, Arjuna sing bagus rupa lan bagus pambudi linuwih kasektene. Wis makaping-kaping sira lan Kakang Prabu Kresna padha mara supaya aku ninggalake Astina lan kumpul karo sira. Yen mangkono, aku padha dene wong kang ora mangerteni babagan budi pakerti lan males kabecikane wong liya.&rdquo;</p><p>Arjuna	: &ldquo;Nanging Kakang, boten wonten klintunipun bilih kula nyuwun Kakang kondur, angempal kalih kadang Pandhawa sarta Ibu Kunthi.&rdquo;</p><p>Adipati Karna	: &ldquo;Yayi Arjuna, dalan sanyatane kanggo nemokake kabagyan sejatiku yaiku lumantar patiku ing tangan sira. Ayo Yayi, terna aku kanggo netepi darmaku! Aturna pamit marang Ibu Kunthi, suwunke ngapura nganti saiki durung bisa gawe muktine lan senenging penggalih Ibu Kunthi sanadyan mung sadhepa bae.&rdquo;</p><p>Punggelan drama ing dhuwur ngandhut perangan <em>setting &hellip;</em></p>\n', '<p>Papan</p>\n', '<p>Panggonan</p>\n', '<p>Kahanan</p>\n', '<p>Wektu </p>\n', '', NULL, NULL, NULL, NULL, NULL, 'C', 1777092996, 1777092996, 1, '', 8, 0, 0),
	(32, 7, 0, 1, 32, 'a:0:{}', NULL, NULL, '<p>Ukara <em>(ngempet metune luh)</em> ing ndhuwur ora dipocapake paraga, nanging diwujudake kanthi solah bawa. Perangan iki diarani &hellip;</p>\n', '<p>Epilog</p>\n', '<p>Monolog</p>\n', '<p>Pandom</p>\n', '<p>Prolog </p>\n', '', NULL, NULL, NULL, NULL, NULL, 'C', 1777092996, 1777092996, 1, '', 8, 0, 0),
	(33, 7, 0, 1, 33, 'a:0:{}', NULL, NULL, '<p>Saka teks ing ndhuwur, bisa dimangerteni watak-wantune paraga. Dene katrangan kang  trep kanggo nuduhake babagan kasebut yaiku &hellip;</p>\n', '<p>Adipati Karna ora teteg amarga nuruti ajakane Arjuna</p>\n', '<p>Arjuna wani lan tega marang kakange dhewe</p>\n', '<p>Adipati Karna nduweni ati kang teguh lan setya</p>\n', '<p>Arjuna ora teteg amarga bisa owah panemu</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'C', 1777092996, 1777092996, 1, '', 8, 0, 0),
	(34, 7, 0, 1, 34, 'a:0:{}', NULL, NULL, '<p>Ing naskah drama kasebut, nalika ana paraga prajurit sing tansah mloka-mlaku ing payudan, nanging mung saklebatan tanpa ngucapke dialog, paraga kasebut diarani &hellip;</p>\n', '<p>Paraga utama</p>\n', '<p>Paraga antagonis</p>\n', '<p>Paraga protagonis</p>\n', '<p>Paraga figuran</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'D', 1777092996, 1777092996, 1, '', 8, 0, 0),
	(35, 7, 0, 1, 35, 'a:0:{}', NULL, NULL, '<p>Pacelaton sing dipocapake Arjuna marang Adipati Karna nggunakake basa &hellip;</p>\n', '<p>Ngoko lugu</p>\n', '<p>Ngoko alus</p>\n', '<p>Krama lugu</p>\n', '<p>Krama alus</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'D', 1777092996, 1777092996, 1, '', 8, 0, 0),
	(36, 7, 0, 1, 36, 'a:0:{}', NULL, NULL, '<p>Basa kuwi digunakake Arjuna amarga &hellip;</p>\n', '<p>Arjuna luwih enom lan ngajeni Adipati Karna</p>\n', '<p>Arjuna luwih tuwa lan kudu diajeni Adipati Karna</p>\n', '<p>Arjuna luwih enom nanging kudu luwih diajeni</p>\n', '<p>Arjuna luwih tuwa lan kudu luwih diajeni</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'A', 1777092996, 1777092996, 1, '', 8, 0, 0),
	(37, 7, 0, 1, 37, 'a:0:{}', NULL, NULL, '<p><strong>Wacanen teks ing ngisor iki kanggo mangsuli pitakonan no 37 - 40!</strong></p><p>Monumen Tetenger Perang Puputan Bayu dumunung ing Desa Bayu, Kecamatan Songgon, Banyuwangi. Tetenger iki didadekake taun 2003 kanggo ngelingi perjuangan para pejuang Blambangan nglawan pasukan VOC ing Perang Puputan Bayu tanggal 18 Desember 1771, sing banjur dadi latar lahire Banyuwangi.</p><p>Ing ndhuwur monumen iki ana lambang Garuda Indonesia sing diapit patung para pejuang. Ing sisih ngisor, ana relief sing nuduhake semangat perang para pahlawan sing melu perang Puputan Bayu. Panggonan iki asring dikunjungi saben tanggal 17-18 Desember kanggo upacara mengeti perjuangan lan tasyakuran dening warga lan pejabat daerah.</p><p>Teks ing ndhuwur kalebu jinis teks dheskripsi. Maksude yaiku &hellip;</p>\n', '<p>Teks kang nggambarake kahanan utawa objek kanthi cetha, rinci, lan apa anane.</p>\n', '<p>Asil susastra awujud larik lan pada kang basane cekak, mentes, lan endah.</p>\n', '<p>Teks kang nyritakake sawijining kedadeyan, tindakan, apadene kahanan kanthi urut lan runtut saka wiwitan nganti pungkasan.</p>\n', '<p>Tembang kang kawengku paugeran guru lagu, guru gatra, lan guru wilangan.</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'A', 1777092996, 1777092996, 1, '', 8, 0, 0),
	(38, 7, 0, 1, 38, 'a:0:{}', NULL, NULL, '<p>Titikane teks kasebut antarane kaya ing ngisor iki, kajaba &hellip;</p><p>	</p>\n', '<p>Nggambarake samubarang objek, upamane kahanan, papan, utawa manungsa</p>\n', '<p>Nggunakake pancadriya (pandeleng, pangrasa, pangrungu, pangganda, lan pangecap)</p>\n', '<p>Bisa ngajak pamaca kaya-kaya pamaca bisa ndeleng, krungu, ngambu, lan ngecap dhewe</p>\n', '<p>Bisa ngajak pamaca mbayangake kedadean ora nyata sing dikarepake panulis.</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'D', 1777092996, 1777092996, 1, '', 8, 0, 0),
	(39, 7, 0, 1, 39, 'a:0:{}', NULL, NULL, '<p>Teks dheskripsi <em>Monumen Tetenger Perang Puputan Bayu </em>ing ndhuwur kalebu jinis &hellip;</p>\n', '<p>Teks dheskripsi subjektif</p>\n', '<p>Teks dheskripsi spasial</p>\n', '<p>Teks dheskripsi  objektif</p>\n', '<p>Imajinatif</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'C', 1777092996, 1777092996, 1, '', 8, 0, 0),
	(40, 7, 0, 1, 40, 'a:0:{}', NULL, NULL, '<p>Teks kuwi ditulis adhedhasar &hellip;</p>\n', '<p>Gagasan</p>\n', '<p>Kasunyatan</p>\n', '<p>Angen-angen</p>\n', '<p>Pangrasa</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'B', 1777092996, 1777092996, 1, '', 8, 0, 0),
	(41, 7, 0, 5, 1, 'a:0:{}', NULL, NULL, '<p>Ing pamentasan drama, kita bisa mangerteni babagan watak wantune saben paraga protagonis utawa antagonis. Watak wantu kang mangkono bisa dimangerteni kanthi saperangan cara. Apa bae cara sing dikarepake? Andharna!</p>\n', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '<p>Watak wantune paraga bisa dimangerteni lumantar tindak-tanduke paraga, pocapane paraga, panggambaran dening pangripta, lan katrangan langsung saka paraga liya</p>\n', 1777092996, 1777092996, 1, '', 8, 0, 0),
	(42, 7, 0, 5, 2, 'a:0:{}', NULL, NULL, '<p>Sapa wae sing kudune nganggo basa krama alus? Sebutna!</p>\n', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '<p>anak marang wong tuwane,</p><p>abdi/rewang marang bendarane/juragane,</p><p>ngisoran/andhahan marang dhedhuwurane,</p><p>wong kaprenah enom marang kaprenah tuwa</p>\n', 1777092996, 1777092996, 1, '', 8, 0, 0),
	(43, 7, 0, 5, 3, 'a:0:{}', NULL, NULL, '<p>Owahana ukara ing ngisor iki nganggo basa krama alus!</p><p><em>Pak, sampean engko apa sida lunga karo pakdhe?</em></p>\n', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '<p>Pak, panjenengan mangke punapa siyos tindak kaliyan pakdhe?</p>\n', 1777092996, 1777092996, 1, '', 8, 0, 0),
	(44, 7, 0, 5, 4, 'a:0:{}', NULL, NULL, '<p>Salinen aksara ing ngisor iki nganggo huruf latin!</p><img src="uploads/bank_soal/img_754_fa3a192cc8ea2ce94cac.png"><img src="uploads/bank_soal/img_754_f53b4dcba955398885ca.png">\n', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '<p>Kabupaten Banyuwangi madeg ing tanggal 18 Desember 1771.</p>\n', 1777092996, 1777092996, 1, '', 8, 0, 0),
	(45, 7, 0, 5, 5, 'a:0:{}', NULL, NULL, '<p>Salinen aksara ing ngisor iki nganggo huruf latin!</p><p><img src="uploads/bank_soal/img_755_45c440ec2acf6b2ec4c2.png"></p>\n', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '<p><em>Sawise wulan Ramadhan, umat muslim bakal ngrayakake Idul Fitri.</em></p>\n', 1777092996, 1777092996, 1, '', 8, 0, 0),
	(46, 8, 0, 1, 1, 'a:0:{}', NULL, NULL, '<p>Berikut kegiatan yang dapat dilakukan untuk mendokumentasikan karya seni rupa, kecuali &hellip;.</p>\n', '<p>mencatat</p>\n', '<p>memotret</p>\n', '<p>menyimpan</p>\n', '<p>menggambar</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'C', 1777093080, 1777093080, 1, '', 8, 0, 0),
	(47, 8, 0, 1, 2, 'a:0:{}', NULL, NULL, '<p>Berikut kekurangan dari jurnal visual digital adalah &hellip;.</p>\n', '<p>sangat bergantung koneksi internet</p>\n', '<p>kemampuan penyimpanan yang besar</p>\n', '<p>kemudahan dalam mengakses</p>\n', '<p>dapat dilihat oleh orang banyak yang berjarak</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'A', 1777093080, 1777093080, 1, '', 8, 0, 0),
	(48, 8, 0, 1, 3, 'a:0:{}', NULL, NULL, '<p>Jurnal visual yang tertangkap dalam gambar akan mengingatkan pada situasi dan perasaan saat itu, serta momen yang mungkin terlupakan karena tertindih momen-momen lainnya. Pernyataan tersebut menunjukkan fungsi jurnal visual, yaitu &hellip;.</p>\n', '<p>refleksi </p>\n', '<p>observasi </p>\n', '<p>eksplorasi</p>\n', '<p>kreas</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'A', 1777093080, 1777093080, 1, '', 8, 0, 0),
	(49, 8, 0, 1, 4, 'a:0:{}', NULL, NULL, '<p>Manfaat penggunaan gambar dalam dokumentasi karya seni rupa adalah &hellip;.</p>\n', '<p>membuat karya seni terlihat cantik</p>\n', '<p>memberikan visualisasi yang jelas tentang karya seni</p>\n', '<p>memudahkan penjualan karya seni</p>\n', '<p>menghilangkan kebutuhan teks</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'B', 1777093080, 1777093080, 1, '', 8, 0, 0),
	(50, 8, 0, 1, 5, 'a:0:{}', NULL, NULL, '<p>Fungsi eksplorasi dari sebuah jurnal visual adalah &hellip;.</p>\n', '<p>merekam objek dan kejadian secara rinci</p>\n', '<p>mengenang situasi dan kejadian yang terekam dalam jurnal</p>\n', '<p>penyalur kreativitas dalam bentuk gambar dan tulisan</p>\n', '<p>sarana menemukan hal-hal baru yang tidak terprediksi</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'D', 1777093080, 1777093080, 1, '', 8, 0, 0),
	(51, 8, 0, 1, 6, 'a:0:{}', NULL, NULL, '<p>Saat menggambar bentuk harus memperhatika nperbandingan yang ideal dan harmonis antara bagian-bagian benda yang menjadi objek model gambar yang dapat diamati (contoh gambar). Hal ini merupakan prinsip menggambar yang disebut &hellip;</p>\n', '<p>komposisi</p>\n', '<p>kesatuan</p>\n', '<p>keseimbangan</p>\n', '<p>proporsi</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'D', 1777093080, 1777093080, 1, '', 8, 0, 0),
	(52, 8, 0, 1, 7, 'a:0:{}', NULL, NULL, '<p>Contoh penerapan design thinking dalam proyek seni rupa di lingkungan sekitar adalah &hellip;.</p>\n', '<p>menggambar potret diri tanpa tujuan tertentu</p>\n', '<p>membuat mural di lingkungan sekitar yang mengangkat isu kebersihan dan kesehatan</p>\n', '<p>melukis pemandangan alam</p>\n', '<p>membuat patung dari bahan mahal</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'B', 1777093080, 1777093080, 1, '', 8, 0, 0),
	(53, 8, 0, 1, 8, 'a:0:{}', NULL, NULL, '<p>Beberapa tipe huruf memiliki karakter atau kepribadian tertentu. Penggambaran bentuk yang menekankan kepada pencapaian karakter, dengan cara menonjolkan karakteristik objek visual itu sendiri disebut &hellip;.</p>\n', '<p>stilasi</p>\n', '<p>distorsi</p>\n', '<p>transformasi</p>\n', '<p>disformasi</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'B', 1777093080, 1777093080, 1, '', 8, 0, 0),
	(54, 8, 0, 1, 9, 'a:0:{}', NULL, NULL, '<p>Sudut mata terhadap objek gambar yang berada di bawah garis horizon sehingga seolah-olah orang yang mengamati objek berada di atas objek disebut &hellip;.</p>\n', '<p>sudut pandang mata burung</p>\n', '<p>sudut pandang mata normal</p>\n', '<p>sudut pandang mata katak</p>\n', '<p>sudut pandang mata kucing</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'A', 1777093080, 1777093080, 1, '', 8, 0, 0),
	(55, 8, 0, 1, 10, 'a:0:{}', NULL, NULL, '<p>Perhatikan ragam hias berikut!</p><p><img src="uploads/bank_soal/img_8110_53dd91812174124deb0c.png"></p><p>Teknik yang digunakan dalam pembuatan ragam hias di atas adalah &hellip;.</p>\n', '<p>distorsi</p>\n', '<p>deformasi</p>\n', '<p>stilasi</p>\n', '<p>jiplak</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'C', 1777093080, 1777093080, 1, '', 8, 0, 0),
	(56, 8, 0, 1, 11, 'a:0:{}', NULL, NULL, '<p>Proses berkarya yang tidak terdapat pada tahap perencanaan adalah &hellip;.</p>\n', '<p>menentukan alat dan bahan</p>\n', '<p>membuat alur pengerjaan</p>\n', '<p>menghitung alokasi waktu</p>\n', '<p>mengevaluasi karya</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'D', 1777093080, 1777093080, 1, '', 8, 0, 0),
	(57, 8, 0, 1, 12, 'a:0:{}', NULL, NULL, '<p>Perhatikan gambar berikut!</p><p><img src="uploads/bank_soal/img_8112_c0e98cff8d9c0299e87c.png"></p><p>Berikut alat dan bahan yang digunakan untuk membuat jurnal visual tersebut, kecuali &hellip;.</p>\n', '<p>pulpen</p>\n', '<p>lem</p>\n', '<p>gunting</p>\n', '<p>kamera</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'D', 1777093080, 1777093080, 1, '', 8, 0, 0),
	(58, 8, 0, 1, 13, 'a:0:{}', NULL, NULL, '<p>Hal pertama yang harus dilakukan sebelum membuat karya adalah ....</p>\n', '<p>membuat jurnal visual</p>\n', '<p>wawancara</p>\n', '<p>membuat prolog</p>\n', '<p>mencari ide</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'D', 1777093080, 1777093080, 1, '', 8, 0, 0),
	(59, 8, 0, 1, 14, 'a:0:{}', NULL, NULL, '<p>Aspek penilaian yang mempertimbangkan hal- hal yang sedang menjadi trend di masyarakat adalah aspek ....</p>\n', '<p>kreativitas</p>\n', '<p>wujud</p>\n', '<p>penguasaan teknik</p>\n', '<p>selera</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'D', 1777093080, 1777093080, 1, '', 8, 0, 0),
	(60, 8, 0, 1, 15, 'a:0:{}', NULL, NULL, '<p>Pelukis yang menganut aliran ekspresionisme atau abstrak adalah &hellip;.</p>\n', '<p>Marcel Duchamp</p>\n', '<p>Affandi Koesuma</p>\n', '<p>Hendra Gunawan</p>\n', '<p>Erica Hestu Wahyuni</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'B', 1777093080, 1777093080, 1, '', 8, 0, 0),
	(61, 8, 0, 1, 16, 'a:0:{}', NULL, NULL, '<p>Menurut Brent G. Wilson, apresiasi seni berkaitan dengan sikap hormat kepada dunia seni rupa, termasuk kepada profesi perupa, hal tersebut merupakan domain ....</p>\n', '<p>feeling</p>\n', '<p>emphatizing</p>\n', '<p>valuing</p>\n', '<p>logam</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'B', 1777093080, 1777093080, 1, '', 8, 0, 0),
	(62, 8, 0, 1, 17, 'a:0:{}', NULL, NULL, '<p>Perhatikan gambar berikut!<img src="uploads/bank_soal/img_8117_14fe3da950932bed117e.png"></p><p>Gambar di atas merupakan salah satu karya seni yang berupa gambar ilustrasi.Jenis ilustrasi yang tepat untuk gambar tersebut adalah ....</p>\n', '<p>kartun</p>\n', '<p>karikatur</p>\n', '<p>komik</p>\n', '<p>karya sastra</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'B', 1777093080, 1777093080, 1, '', 8, 0, 0),
	(63, 8, 0, 1, 18, 'a:0:{}', NULL, NULL, '<p>Gambar sederhana atau draf kasar yang dibuat secara global untuk melukiskan bagian-bagian pokok yang ingin diungkapkan oleh pembuatnya disebut ....</p>\n', '<p>model</p>\n', '<p>tiruan</p>\n', '<p>lukisan</p>\n', '<p>sketsa</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'D', 1777093080, 1777093080, 1, '', 8, 0, 0),
	(64, 8, 0, 1, 19, 'a:0:{}', NULL, NULL, '<p>Teknik menggosok dalam gambar bentuk disebut ....</p>\n', '<p>dusel</p>\n', '<p>pointilis</p>\n', '<p>acak</p>\n', '<p>gradatif</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'A', 1777093080, 1777093080, 1, '', 8, 0, 0),
	(65, 8, 0, 1, 20, 'a:0:{}', NULL, NULL, '<p>Berikut yang bukan termasuk cara seni dapat membawa perubahan sosial adalah ....</p><p>	</p>\n', '<p>mengadakan pameran seni bertema lingkungan</p>\n', '<p>membuat film dokumenter tentang masalah sosial</p>\n', '<p>menggunakan lagu-lagu untuk mengkritik ketidakadilan</p>\n', '<p>menyimpan karya seni di galeri pribadi untuk koleksi pribadi</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'D', 1777093080, 1777093080, 1, '', 8, 0, 0),
	(66, 8, 0, 1, 21, 'a:0:{}', NULL, NULL, '<p>Perhatikan gambar berikut!</p><p><img src="uploads/bank_soal/img_8121_4a3434cb2d6e9859cb98.png"></p><p>Logo di atas merupakan contoh logo yang berupa ....</p>\n', '<p>initial perusahaan</p>\n', '<p>piktorial perusahaan</p>\n', '<p>wordmark perusahaan</p>\n', '<p>abstrak dari pabrikan</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'B', 1777093080, 1777093080, 1, '', 8, 0, 0),
	(67, 8, 0, 1, 22, 'a:0:{}', NULL, NULL, '<p>Persamaan antara karya seni mozaik dan kolase, yaitu ....</p>\n', '<p>karya seni tersebut dibuat dengan teknik tempel</p>\n', '<p>menggunakan medium yang mahal</p>\n', '<p>memerlukan kreativitas dan keterampilan tinggi</p>\n', '<p>sulit dibuat</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'A', 1777093080, 1777093080, 1, '', 8, 0, 0),
	(68, 8, 0, 1, 23, 'a:0:{}', NULL, NULL, '<p>Perhatikan gambar berikut!</p><p><img src="uploads/bank_soal/img_8123_54643c4bb0f21df4947e.png"></p><p>Bahan yang digunakan pada karya di atas adalah ...</p>\n', '<p>kaca </p>\n', '<p>biji-bijian</p>\n', '<p>daun-daunan</p>\n', '<p>keramik</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'B', 1777093080, 1777093080, 1, '', 8, 0, 0),
	(69, 8, 0, 1, 24, 'a:0:{}', NULL, NULL, '<p>Aliran seni lukis yang menghadirkan gambar objek yang nyata dalam keadaan tidak mungkin terjadi di dalam dunia nyata adalah ....</p>\n', '<p>kubisme</p>\n', '<p>surealisme</p>\n', '<p>naturalisme</p>\n', '<p>impresionisme</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'B', 1777093080, 1777093080, 1, '', 8, 0, 0),
	(70, 8, 0, 1, 25, 'a:0:{}', NULL, NULL, '<p>Perhatikan gambar lukisan berikut!</p><p><img src="uploads/bank_soal/img_8125_b13142c48918c09b6a7b.png"></p><p>Gambar di atas merupakan lukisan berjudul</p><p>&ldquo;Kebijaksanaan dari Timur&rdquo; karya salah satu</p><p>maestro ternama Indonesia, yaitu ...</p>\n', '<p>Affandi Koesoema</p>\n', '<p>Raden Saleh</p>\n', '<p>Barli Sasmitawinata</p>\n', '<p>Abdullah Suriosubroto</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'A', 1777093080, 1777093080, 1, '', 8, 0, 0),
	(71, 8, 0, 1, 26, 'a:0:{}', NULL, NULL, '<p>Teknik yang digunakan dalam gambar berikut adalah &hellip;.</p><p><img src="uploads/bank_soal/img_8126_d33e3b675bd9566c6782.png"></p>\n', '<p>dusel</p>\n', '<p>sapuan basah</p>\n', '<p>pointilis</p>\n', '<p>blok</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'A', 1777093080, 1777093080, 1, '', 8, 0, 0),
	(72, 8, 0, 1, 27, 'a:0:{}', NULL, NULL, '<p>Teknik pengecapan cat ke permukaan kertas yang meninggalkan visual berupa guratan- guratan warna saling bertabrakan tidak teratur, ekspresif, mengalir dinamis, dan cenderung ke abstrak disebut teknik &hellip;.</p>\n', '<p>mixed media</p>\n', '<p>zentangle</p>\n', '<p>swirl painting</p>\n', '<p>moodboard</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'C', 1777093080, 1777093080, 1, '', 8, 0, 0),
	(73, 8, 0, 1, 28, 'a:0:{}', NULL, NULL, '<p>Berikut merupakan aturan yang harus diperhatikan dalam menggambar, kecuali &hellip;.</p>\n', '<p>background atau latar belakang</p>\n', '<p>pola bentuk ragam hias yang akan digambar</p>\n', '<p>ukuran pola gambar yang akan dibuat</p>\n', '<p>mewarnai gambar</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'A', 1777093080, 1777093080, 1, '', 8, 0, 0),
	(74, 8, 0, 1, 29, 'a:0:{}', NULL, NULL, '<p>Unsur menggambar atau seni rupa yang terbentuk dengan memadukan dua titik yang terpisah dan memanjang disebut &hellip;.</p>\n', '<p>Ruang</p>\n', '<p>bidang</p>\n', '<p>garis</p>\n', '<p>bentuk</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'C', 1777093080, 1777093080, 1, '', 8, 0, 0),
	(75, 8, 0, 1, 30, 'a:0:{}', NULL, NULL, '<p>Pernyataan paling benar mengenai unsur gelap terang adalah &hellip;.</p>\n', '<p>jika cahaya datang dari atas benda atau objek, maka seluruh permukaan objek akan terlihat terang</p>\n', '<p> jika cahaya datang dari atas sebelah kanan, maka permukaan objek sebelah kanan akan terang dan permukaan sebelah kiri terlihat gelap</p>\n', '<p>jika cahaya datang dari atas sebelah kiri, maka permukaan sebelah kiri akan terlihat terang, dan permukaan sebelah kanan terlihat gelap, serta membentuk bayangan benda di sebelah kanan</p>\n', '<p>jika cahaya datang dari atas sebelah kiri, maka permukaan sebelah kiri dan kanan akan terlihat terang, dan membentuk bayangan benda di sebelah kanan</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'C', 1777093080, 1777093080, 1, '', 8, 0, 0),
	(76, 8, 0, 1, 31, 'a:0:{}', NULL, NULL, '<p>Prinsip seni rupa yang digunakan dalam menggambar model adalah &hellip;.</p>\n', '<p>komposisi</p>\n', '<p>irama</p>\n', '<p>penekanan</p>\n', '<p>keseimbangan</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'D', 1777093080, 1777093080, 1, '', 8, 0, 0),
	(77, 8, 0, 1, 32, 'a:0:{}', NULL, NULL, '<p>Menempelkan gambar pada karton atau papan tripleks dengan perbandingan tertentu disebut &hellip;.</p>\n', '<p>mounting</p>\n', '<p>matting</p>\n', '<p>framming</p>\n', '<p>pasparto</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'A', 1777093080, 1777093080, 1, '', 8, 0, 0),
	(78, 8, 0, 1, 33, 'a:0:{}', NULL, NULL, '<p>Perhatikan gambar berikut!</p><p><img src="uploads/bank_soal/img_8133_7bb2a21489fc6026c3b7.png"></p><p>Tempat meletakkan display pameran di atas dinamakan &hellip;.</p>\n', '<p>gantungan</p>\n', '<p>panil</p>\n', '<p>booth camp</p>\n', '<p>stage</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'B', 1777093080, 1777093080, 1, '', 8, 0, 0),
	(79, 8, 0, 1, 34, 'a:0:{}', NULL, NULL, '<p>Analisis prinsip pada seni rupa dilakukan dengan mengkaji hal-hal berikut, kecuali &hellip;.</p>\n', '<p>keselarasan</p>\n', '<p>penguatan</p>\n', '<p>kesebandingan </p>\n', '<p>penekanan</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'B', 1777093080, 1777093080, 1, '', 8, 0, 0),
	(80, 8, 0, 1, 35, 'a:0:{}', NULL, NULL, '<p>Bahan yang digunakan untuk membuat jurnal visual dengan teknik menempel adalah &hellip;.</p>\n', '<p>lukisan</p>\n', '<p>rekaman video</p>\n', '<p>hasil penelitian</p>\n', '<p>potongan gambar</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'D', 1777093080, 1777093080, 1, '', 8, 0, 0),
	(81, 8, 0, 1, 36, 'a:0:{}', NULL, NULL, '<p>Kumpulan dokumentasi proses berkarya yang lengkap dan berurutan sesuai dengan waktu berprosesnya disebut &hellip;.	</p>\n', '<p>jadwal harian</p>\n', '<p>catatan karya</p>\n', '<p>timeline</p>\n', '<p>jurnal visual</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'D', 1777093080, 1777093080, 1, '', 8, 0, 0),
	(82, 8, 0, 1, 37, 'a:0:{}', NULL, NULL, '<p>Perhatikan gambar berikut!</p><p><img src="uploads/bank_soal/img_8137_494c986bc012c89c2acf.png"></p><p>Teknik yang digunakan untuk membuat jurnal yang sesuai dengan gambar tersebut adalah &hellip;.</p>\n', '<p>menempel</p>\n', '<p>memotret</p>\n', '<p>menulis</p>\n', '<p>menggambar</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'C', 1777093080, 1777093080, 1, '', 8, 0, 0),
	(83, 8, 0, 1, 38, 'a:0:{}', NULL, NULL, '<p>Fungsi evaluasi yang dapat menyeleksi kompetensi yang sesuai dengan standar yang ditetapkan disebut fungsi &hellip;</p>\n', '<p>penempatan</p>\n', '<p>pengukuran keberhasilan</p>\n', '<p>selektif</p>\n', '<p>diagnosis</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'C', 1777093080, 1777093080, 1, '', 8, 0, 0),
	(84, 8, 0, 1, 39, 'a:0:{}', NULL, NULL, '<p>Penyusunan struktur organisasi kepanitiaan pameran disesuaikan dengan &hellip;.</p>\n', '<p>pameran patung, pameran kriya, dan pameran seni grafis</p>\n', '<p>tingkat kebutuhan, situasi, dan kondisi sekolah</p>\n', '<p>apresiasi masyarakat luas</p>\n', '<p>penataan dan sirkulasi pengunjung</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'B', 1777093080, 1777093080, 1, '', 8, 0, 0),
	(85, 8, 0, 1, 40, 'a:0:{}', NULL, NULL, '<p>Berikut yang bukan tahapan dalam menggambar ragam hias adalah ....</p>\n', '<p>menentukan jenis objek yang akan dibuat gambar ragam hiasnya</p>\n', '<p>membuat garis tepi pada kertas</p>\n', '<p>membuat pola gambar ragam hiasnya</p>\n', '<p>memberi warna pada hasil gambar ragam hiasnya</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'B', 1777093080, 1777093080, 1, '', 8, 0, 0),
	(86, 8, 0, 5, 1, 'a:0:{}', NULL, NULL, '<p>Jelaskan tentang teknik penyajian memotret jurnal visual!</p>\n', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '<p>Teknik ini dilakukan dengan cara merekam suara atau gambar pemikiran atau kejadian yang dianggap pentint dalam proses pembuatan karya. Alat utama yang dibutuhkan adaklah alat perekam seperti gawai dan recorder</p>\n', 1777093080, 1777093080, 1, '', 8, 0, 0),
	(87, 8, 0, 5, 2, 'a:0:{}', NULL, NULL, '<p>Perhatikan ilustrasi berikut! Anda akan membuat sebuah karya seni patung yang terinspirasi dari seorang tokoh pejuang kemerdekaan. Tuliskan informasi berupa proses pencarian ide yang bisa Anda tuangkan dalam jurnal visual berdasarkan ilustrasi tersebut! </p>\n', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '<p>Kreativitas murid</p>\n', 1777093080, 1777093080, 1, '', 8, 0, 0),
	(88, 8, 0, 5, 3, 'a:0:{}', NULL, NULL, '<p>Apakah yang dilakukan dalam kegiatan apresiasi?</p>\n', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '<p>Kegiatan apresiasi yaitu melakukan pengamatan , penilaian atau evaluasi dan mengkritik</p>\n', 1777093080, 1777093080, 1, '', 8, 0, 0),
	(89, 8, 0, 5, 4, 'a:0:{}', NULL, NULL, '<p>Sebutkan dan jelaskan metode yang sering digunakan untuk mengevaluasi karya seni rupa</p>\n', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '<p>Metode global dan metode analisis.</p><ol>\n<li>Metode global : menganggap karya seni rupa sebagai suatu kebulatan yang utuh. Namun metode ini cenderung bersifat subjektif sehingga menuntut evaluator lebih banyak bekerja secara intuitif dan emosional.</li>\n<li>Metode analis: mengevaluasi karya seni rupa dengan melihat unsur-unsur seni rupa, hubungan antar unsur dan pengorganisasiannya. Metode ini bersifat objectif dan cocok digunakan dalam bidang akademik.</li>\n</ol>\n', 1777093080, 1777093080, 1, '', 8, 0, 0),
	(90, 8, 0, 5, 5, 'a:0:{}', NULL, NULL, '<p>Jelaskan teknik pointilis dalam menggambar sebuah karya!</p>\n', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '<p>Teknik pointilis adalah teknik atau cara menggambar dengan titik titik untuk menentukan gelap terangnya pada objek suatu gambar dengan menggunakan alat seperti pensil dan pena.</p>\n', 1777093080, 1777093080, 1, '', 8, 0, 0),
	(126, 1, 0, 1, 1, 'a:0:{}', NULL, NULL, '<p>Soal matematika 1</p>\n', '<p> 22.536</p>\n', '<p> 1.431</p>\n', '<p>-1.431</p>\n', '<p>-22.536</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'A', 1777260096, 1777260096, 1, '', 8, 0, 0),
	(127, 1, 0, 1, 2, 'a:0:{}', NULL, NULL, '<p>Soal matematika 2</p>\n', '<p>25 April 2026</p>\n', '<p>26 April 2026</p>\n', '<p>29 April 2026</p>\n', '<p>30 April 2026</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'B', 1777260096, 1777260096, 1, '', 8, 0, 0),
	(128, 1, 0, 1, 3, 'a:0:{}', NULL, NULL, '<p>Soal matematika 3</p>\n', '<p>2 dan 1</p>\n', '<p>3 dan 2</p>\n', '<p>4 dan 3</p>\n', '<p>6 dan 5</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'C', 1777260096, 1777260096, 1, '', 8, 0, 0),
	(129, 1, 0, 1, 4, 'a:0:{}', NULL, NULL, '<p>Soal matematika 4</p>\n', '<p>Tahap 1 ,Tahap 2, Tahap 3 Tahap 4</p>\n', '<p>Tahap 1 ,Tahap 3, Tahap 2 Tahap 4</p>\n', '<p>Tahap 2 ,Tahap 1, Tahap 3 Tahap 4</p>\n', '<p>Tahap 3 ,Tahap 2, Tahap 1 Tahap 4</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'B', 1777260096, 1777260096, 1, '', 8, 0, 0),
	(130, 1, 0, 1, 5, 'a:0:{}', NULL, NULL, '<p>Soal matematika 5</p>\n', '<p>40</p>\n', '<p>30</p>\n', '<p>24</p>\n', '<p>16 </p>\n', '', NULL, NULL, NULL, NULL, NULL, 'A', 1777260096, 1777260096, 1, '', 8, 0, 0),
	(131, 1, 0, 1, 6, 'a:0:{}', NULL, NULL, '<p>Soal matematika 6</p>\n', '<p>26</p>\n', '<p>28</p>\n', '<p>30</p>\n', '<p>32</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'D', 1777260096, 1777260096, 1, '', 8, 0, 0),
