	(383, 10, 0, 1, 8, 'a:0:{}', NULL, NULL, '<p>Dalam nomer atletik ada salah satu nomor yaitu jalan cepat. Pada jalan cepat, salah satu kaki harus selalu ....</p>\n', '<p>Melayang</p>\n', '<p>Menekuk</p>\n', '<p>Menyentuh tanah</p>\n', '<p>Diangkat tinggi</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'C', 1777345664, 1777345664, 1, '', 8, 0, 0),
