	(394, 10, 0, 1, 19, 'a:0:{}', NULL, NULL, '<p>Dalam nomor atletik, tahapan lompat jauh setelah melakukan awalan adalah ....</p>\n', '<p>Melayang</p>\n', '<p>Tolakan</p>\n', '<p>Mendarat</p>\n', '<p>Berlari</p>\n', '', NULL, NULL, NULL, NULL, NULL, 'B', 1777345664, 1777345664, 1, '', 8, 0, 0),
